import { ROUTES } from "@/constants/routes";
import type {
  PassportGroupSubmissionFilter,
  PassportGroupSubmissionSort,
} from "../api/passports.api";

export type PassportGroupViewMode = "table" | "docs";

export interface PassportGroupViewState {
  search: string;
  submissionFilter: PassportGroupSubmissionFilter;
  sortBy: PassportGroupSubmissionSort;
  sortOrder: "asc" | "desc";
  page: number;
  viewMode: PassportGroupViewMode;
}

export interface PassportDetailNavigationState {
  token: string | null;
  groupId: string;
  includeDeleted: boolean;
  viewState: PassportGroupViewState;
}

export interface StoredPassportNavigationContext
  extends PassportDetailNavigationState {
  version: 1;
  token: string;
  userId: string;
  orderedSubmissionIds: string[];
  createdAt: number;
}

const DEFAULT_VIEW_STATE: PassportGroupViewState = {
  search: "",
  submissionFilter: "all",
  sortBy: "name",
  sortOrder: "asc",
  page: 1,
  viewMode: "table",
};

const SUBMISSION_FILTERS = new Set<PassportGroupSubmissionFilter>([
  "all",
  "pending_ai",
  "ai_approved",
  "needs_review",
  "staff_approved",
  "duplicates",
  "document_follow_up",
]);
const SORT_FIELDS = new Set<PassportGroupSubmissionSort>([
  "name",
  "updated_at",
  "verification_confidence",
]);
const SORT_ORDERS = new Set<PassportGroupViewState["sortOrder"]>(["asc", "desc"]);
const VIEW_MODES = new Set<PassportGroupViewMode>(["table", "docs"]);
const STORAGE_PREFIX = "passdetection:passport-navigation:";
const CONTEXT_TTL_MS = 12 * 60 * 60 * 1000;
const MAX_NAVIGATION_ITEMS = 10_000;
const TOKEN_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

type SearchParamsReader = Pick<URLSearchParams, "get">;

export function parsePassportGroupViewState(
  params: SearchParamsReader,
  prefix = "",
): PassportGroupViewState {
  return {
    search: (params.get(`${prefix}q`) ?? "").trim().slice(0, 200),
    submissionFilter: readEnum(
      params.get(`${prefix}filter`),
      SUBMISSION_FILTERS,
      DEFAULT_VIEW_STATE.submissionFilter,
    ),
    sortBy: readEnum(
      params.get(`${prefix}sort`),
      SORT_FIELDS,
      DEFAULT_VIEW_STATE.sortBy,
    ),
    sortOrder: readEnum(
      params.get(`${prefix}order`),
      SORT_ORDERS,
      DEFAULT_VIEW_STATE.sortOrder,
    ),
    page: readPositiveInteger(params.get(`${prefix}page`)),
    viewMode: readEnum(
      params.get(`${prefix}view`),
      VIEW_MODES,
      DEFAULT_VIEW_STATE.viewMode,
    ),
  };
}

export function buildPassportGroupHref(
  groupId: string,
  state: PassportGroupViewState,
  includeDeleted: boolean,
) {
  const params = serializeViewState(state);
  if (includeDeleted) params.set("old_data", "1");
  const query = params.toString();
  const pathname = ROUTES.dashboard.passportGroup(groupId);
  return query ? `${pathname}?${query}` as const : pathname;
}

export function buildPassportDetailNavigationHref(
  submissionId: string,
  navigation: PassportDetailNavigationState,
) {
  const params = serializeViewState(navigation.viewState, "nav_");
  params.set("nav_group", navigation.groupId);
  if (navigation.includeDeleted) params.set("nav_old_data", "1");
  if (navigation.token) params.set("nav", navigation.token);
  return `${ROUTES.dashboard.passportDetail(submissionId)}?${params.toString()}` as const;
}

export function parsePassportDetailNavigation(
  params: SearchParamsReader,
): PassportDetailNavigationState | null {
  const groupId = (params.get("nav_group") ?? "").trim();
  if (!isUuid(groupId)) return null;
  const tokenValue = (params.get("nav") ?? "").trim();
  return {
    token: TOKEN_PATTERN.test(tokenValue) ? tokenValue : null,
    groupId,
    includeDeleted: params.get("nav_old_data") === "1",
    viewState: parsePassportGroupViewState(params, "nav_"),
  };
}

export function createPassportNavigationToken() {
  if (typeof window === "undefined" || !window.crypto?.randomUUID) return null;
  return window.crypto.randomUUID();
}

export function storePassportNavigationContext(
  context: Omit<StoredPassportNavigationContext, "version" | "createdAt">,
) {
  if (
    typeof window === "undefined"
    || !TOKEN_PATTERN.test(context.token)
    || !isUuid(context.userId)
    || !isUuid(context.groupId)
    || context.orderedSubmissionIds.length > MAX_NAVIGATION_ITEMS
    || context.orderedSubmissionIds.some((id) => !isUuid(id))
  ) {
    return false;
  }

  const stored: StoredPassportNavigationContext = {
    ...context,
    version: 1,
    createdAt: Date.now(),
    orderedSubmissionIds: [...context.orderedSubmissionIds],
  };
  try {
    window.sessionStorage.setItem(
      navigationStorageKey(context.userId, context.token),
      JSON.stringify(stored),
    );
    pruneExpiredNavigationContexts(context.userId, context.token);
    return true;
  } catch {
    return false;
  }
}

export function readPassportNavigationContext({
  token,
  userId,
  groupId,
}: {
  token: string | null;
  userId: string | null | undefined;
  groupId: string;
}): StoredPassportNavigationContext | null {
  if (
    typeof window === "undefined"
    || !token
    || !userId
    || !TOKEN_PATTERN.test(token)
    || !isUuid(userId)
    || !isUuid(groupId)
  ) {
    return null;
  }

  const key = navigationStorageKey(userId, token);
  try {
    const raw = window.sessionStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<StoredPassportNavigationContext>;
    if (
      parsed.version !== 1
      || parsed.token !== token
      || parsed.userId !== userId
      || parsed.groupId !== groupId
      || typeof parsed.createdAt !== "number"
      || parsed.createdAt > Date.now() + 60_000
      || Date.now() - parsed.createdAt > CONTEXT_TTL_MS
      || !Array.isArray(parsed.orderedSubmissionIds)
      || parsed.orderedSubmissionIds.length > MAX_NAVIGATION_ITEMS
      || parsed.orderedSubmissionIds.some((id) => !isUuid(id))
      || !isValidViewState(parsed.viewState)
      || typeof parsed.includeDeleted !== "boolean"
    ) {
      window.sessionStorage.removeItem(key);
      return null;
    }
    return parsed as StoredPassportNavigationContext;
  } catch {
    // Storage access and cleanup can both be denied by browser privacy settings.
    try { window.sessionStorage.removeItem(key); } catch { /* Use server navigation instead. */ }
    return null;
  }
}

export function isPassportNavigationKeyboardTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  if (["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName)) return true;
  const role = target.getAttribute("role");
  return role === "textbox" || role === "combobox" || role === "spinbutton";
}

function serializeViewState(state: PassportGroupViewState, prefix = "") {
  const params = new URLSearchParams();
  if (state.search) params.set(`${prefix}q`, state.search);
  if (state.submissionFilter !== DEFAULT_VIEW_STATE.submissionFilter) {
    params.set(`${prefix}filter`, state.submissionFilter);
  }
  if (state.sortBy !== DEFAULT_VIEW_STATE.sortBy) {
    params.set(`${prefix}sort`, state.sortBy);
  }
  if (state.sortOrder !== DEFAULT_VIEW_STATE.sortOrder) {
    params.set(`${prefix}order`, state.sortOrder);
  }
  if (state.page !== DEFAULT_VIEW_STATE.page) {
    params.set(`${prefix}page`, String(state.page));
  }
  if (state.viewMode !== DEFAULT_VIEW_STATE.viewMode) {
    params.set(`${prefix}view`, state.viewMode);
  }
  return params;
}

function readEnum<T extends string>(
  value: string | null,
  allowed: ReadonlySet<T>,
  fallback: T,
) {
  return value !== null && allowed.has(value as T) ? value as T : fallback;
}

function readPositiveInteger(value: string | null) {
  if (!value || !/^\d+$/.test(value)) return DEFAULT_VIEW_STATE.page;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed >= 1 ? parsed : DEFAULT_VIEW_STATE.page;
}

function isUuid(value: unknown): value is string {
  return typeof value === "string" && UUID_PATTERN.test(value);
}

function isValidViewState(value: unknown): value is PassportGroupViewState {
  if (!value || typeof value !== "object") return false;
  const state = value as Partial<PassportGroupViewState>;
  return (
    typeof state.search === "string"
    && state.search.length <= 200
    && SUBMISSION_FILTERS.has(state.submissionFilter as PassportGroupSubmissionFilter)
    && SORT_FIELDS.has(state.sortBy as PassportGroupSubmissionSort)
    && SORT_ORDERS.has(state.sortOrder as PassportGroupViewState["sortOrder"])
    && Number.isSafeInteger(state.page)
    && Number(state.page) >= 1
    && VIEW_MODES.has(state.viewMode as PassportGroupViewMode)
  );
}

function navigationStorageKey(userId: string, token: string) {
  return `${STORAGE_PREFIX}${userId}:${token}`;
}

function pruneExpiredNavigationContexts(userId: string, activeToken: string) {
  const prefix = `${STORAGE_PREFIX}${userId}:`;
  const expiredKeys: string[] = [];
  for (let index = 0; index < window.sessionStorage.length; index += 1) {
    const key = window.sessionStorage.key(index);
    if (!key?.startsWith(prefix) || key.endsWith(activeToken)) continue;
    try {
      const parsed = JSON.parse(
        window.sessionStorage.getItem(key) ?? "",
      ) as { createdAt?: unknown };
      if (
        typeof parsed.createdAt !== "number"
        || Date.now() - parsed.createdAt > CONTEXT_TTL_MS
      ) {
        expiredKeys.push(key);
      }
    } catch {
      expiredKeys.push(key);
    }
  }
  expiredKeys.forEach((key) => window.sessionStorage.removeItem(key));
}

import type {
  ExtractedPassportFields,
  PassportPostSubmissionVerification,
  PassportSubmission,
  StaffApprovalOutcome,
  StaffApprovalRequest,
  PassportVerificationField,
  PassportVerificationFieldName,
  PassportVerificationVerdict,
} from "@/types/passport.types";

export const PASSPORT_REVIEW_FIELDS = [
  "surname",
  "given_names",
  "passport_number",
  "nationality",
  "place_of_issue",
  "date_of_birth",
  "date_of_issue",
  "date_of_expiry",
  "sex",
] as const satisfies readonly PassportVerificationFieldName[];

export type PassportReviewFieldName = typeof PASSPORT_REVIEW_FIELDS[number];

export type PassportFieldReview = Omit<PassportVerificationField, "verdict"> & {
  verdict: Exclude<PassportVerificationVerdict, "correct">;
  label: "Incorrect" | "Suspicious" | "Not verified";
};

export type StaffApprovalFeedbackKind =
  | "success"
  | "already_approved"
  | "record_changed"
  | "unavailable"
  | "temporary_error";

export interface StaffApprovalFeedback {
  kind: StaffApprovalFeedbackKind;
  message: string;
}

export function cleanPassportReviewFields(
  fields: Record<string, string>,
): Record<string, string> {
  return Object.fromEntries(
    PASSPORT_REVIEW_FIELDS.flatMap((field) => {
      if (!Object.prototype.hasOwnProperty.call(fields, field)) return [];
      const value = fields[field]?.trim() ?? "";
      return value || field === "surname"
        ? [[field, value] as const]
        : [];
    }),
  );
}

export function buildStaffApprovalRequest(
  fields: Record<string, string>,
  expectedExtractionRevision: number,
  reviewReason?: string,
): StaffApprovalRequest {
  const normalizedReason = reviewReason?.trim();
  return {
    confirmedFields: cleanPassportReviewFields(fields),
    expectedExtractionRevision,
    ...(normalizedReason ? { reviewReason: normalizedReason } : {}),
  };
}

export function getStaffApprovalOutcomeFeedback(
  outcome: StaffApprovalOutcome,
): StaffApprovalFeedback {
  if (outcome === "already_approved") {
    return {
      kind: "already_approved",
      message: (
        "This passport was already approved. The latest saved approval is shown "
        + "and no duplicate action was created."
      ),
    };
  }
  return {
    kind: "success",
    message: "Passport approved and reviewed corrections saved.",
  };
}

export function getStaffApprovalErrorFeedback(
  error: unknown,
): StaffApprovalFeedback {
  const candidate = (
    error && typeof error === "object"
      ? error as { code?: unknown; message?: unknown }
      : null
  );
  const code = typeof candidate?.code === "string" ? candidate.code : "";
  const serverMessage = (
    typeof candidate?.message === "string" && candidate.message.trim()
      ? candidate.message.trim()
      : null
  );

  if (code === "STAFF_APPROVAL_STALE") {
    return {
      kind: "record_changed",
      message: (
        serverMessage
        ?? "This passport changed after you opened it. Review the refreshed record and approve again."
      ),
    };
  }
  if (
    code === "STAFF_APPROVAL_UNAVAILABLE"
    || code === "VALIDATION_ERROR"
    || code === "AUTHORIZATION_ERROR"
  ) {
    return {
      kind: "unavailable",
      message: (
        serverMessage
        ?? "This passport is not currently available for staff approval."
      ),
    };
  }
  return {
    kind: "temporary_error",
    message: (
      serverMessage
      ?? "The approval response could not be confirmed. Refresh and safely retry."
    ),
  };
}

type VerificationSource = Pick<
  PassportSubmission,
  "status" | "post_submission_verification"
>;

type ReviewerSource = Pick<
  PassportSubmission,
  | "verification_reviewed_by_user_id"
  | "verification_reviewer_name"
>;

const RETRYABLE_AI_PROVIDER_STATUSES = new Set([
  "manual_review_required",
  "network_error",
  "provider_unavailable",
  "rate_limited",
  "timeout",
]);
const NO_READABLE_EVIDENCE_REASON_CODES = new Set([
  "unreadable",
  "missing_submitted_value",
]);

export function canRetryPassportAiVerification(
  passport: VerificationSource,
) {
  if (passport.status !== "needs_review") return false;
  const providerStatus = passport.post_submission_verification?.provider_status;
  return typeof providerStatus === "string"
    && RETRYABLE_AI_PROVIDER_STATUSES.has(providerStatus.trim().toLowerCase());
}

export function getPassportFieldReview(
  passport: VerificationSource,
  validation: ExtractedPassportFields["field_validation"] | undefined,
  field: PassportReviewFieldName,
): PassportFieldReview | null {
  if (passport.status === "needs_review") {
    const verification = passport.post_submission_verification;
    if (verification?.stale_after_staff_edit) {
      return {
        field,
        verdict: "suspicious",
        label: "Not verified",
        observed_value: null,
        confidence: 0,
        reason_code: "passport_record_changed",
      };
    }
    const providerUnavailable = typeof verification?.provider_status === "string"
      && RETRYABLE_AI_PROVIDER_STATUSES.has(
        verification.provider_status.trim().toLowerCase(),
    );
    const decisions = Array.isArray(verification?.fields) ? verification.fields : [];
    const decision = decisions.find((item) => item.field === field);
    if (decision?.verdict === "correct") return null;
    if (decision?.verdict === "suspicious" || decision?.verdict === "incorrect") {
      return {
        field,
        verdict: decision.verdict,
        observed_value: decision.observed_value,
        confidence: decision.confidence,
        reason_code: decision.reason_code,
        label: providerUnavailable
          ? "Not verified"
          : decision.verdict === "incorrect"
            ? "Incorrect"
            : "Suspicious",
      };
    }

    const incorrectFields = Array.isArray(verification?.incorrect_fields)
      ? verification.incorrect_fields
      : [];
    const suspiciousFields = Array.isArray(verification?.suspicious_fields)
      ? verification.suspicious_fields
      : [];
    const listedVerdict = incorrectFields.includes(field)
      ? "incorrect"
      : suspiciousFields.includes(field)
        ? "suspicious"
        : null;
    if (listedVerdict) {
      return {
        field,
        verdict: listedVerdict,
        label: providerUnavailable
          ? "Not verified"
          : listedVerdict === "incorrect"
            ? "Incorrect"
            : "Suspicious",
        observed_value: null,
        confidence: verification?.confidence ?? 0,
        reason_code: verification?.reason_code ?? "manual_review_required",
      };
    }

    if (decisions.length > 0 || incorrectFields.length > 0 || suspiciousFields.length > 0) {
      return null;
    }

    return {
      field,
      verdict: "suspicious",
      label: "Not verified",
      observed_value: null,
      confidence: verification?.confidence ?? 0,
      reason_code: verification?.reason_code ?? "verification_result_unavailable",
    };
  }

  const issue = validation?.issues?.find((candidate) => validationIssueMatchesField(candidate, field));
  if (!issue) return null;
  return {
    field,
    verdict: issue.severity.toLowerCase() === "error" ? "incorrect" : "suspicious",
    label: issue.severity.toLowerCase() === "error" ? "Incorrect" : "Suspicious",
    observed_value: null,
    confidence: 0,
    reason_code: issue.message,
  };
}

export function getPassportFieldReviewClassName(verdict?: PassportFieldReview["verdict"]) {
  if (verdict === "incorrect") {
    return "border-red-400 bg-red-50 hover:border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-200";
  }
  if (verdict === "suspicious") {
    return "border-amber-400 bg-amber-50 hover:border-amber-500 focus:border-amber-500 focus:ring-2 focus:ring-amber-200";
  }
  return "border-slate-200 bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100";
}

export function formatPassportFieldReviewConfidence(
  review: Pick<
    PassportFieldReview,
    "confidence" | "observed_value" | "reason_code"
  >,
) {
  if (
    !review.observed_value?.trim()
    || NO_READABLE_EVIDENCE_REASON_CODES.has(review.reason_code.trim().toLowerCase())
    || !Number.isFinite(review.confidence)
    || review.confidence <= 0
  ) {
    return null;
  }
  const percentage = review.confidence <= 1
    ? review.confidence * 100
    : Math.min(100, review.confidence);
  return `${Math.round(percentage)}% confidence`;
}

export function getPassportVerificationConfidence(
  verification: PassportPostSubmissionVerification,
) {
  if (verification.stale_after_staff_edit) return null;
  const containsLegacyInflatedUnreadableConfidence = verification.fields.some(
    (field) =>
      field.confidence > 0
      && (
        !field.observed_value?.trim()
        || NO_READABLE_EVIDENCE_REASON_CODES.has(
          field.reason_code.trim().toLowerCase(),
        )
      ),
  );
  if (
    containsLegacyInflatedUnreadableConfidence
    || !Number.isFinite(verification.confidence)
  ) {
    return null;
  }
  return verification.confidence;
}

export function getPassportReviewActionState(
  status: PassportSubmission["status"],
  isSaving: boolean,
) {
  if (isSaving) {
    return {
      disabled: true,
      label: status === "needs_review"
        ? "Approving and saving corrections"
        : "Saving Review",
    };
  }

  const inactiveLabels: Partial<Record<PassportSubmission["status"], string>> = {
    pending_extraction: "Extraction Pending",
    extracting: "Extraction in Progress",
    processing: "Extraction in Progress",
    ready_for_client_review: "Awaiting Client Review",
  };
  const inactiveLabel = inactiveLabels[status];
  if (inactiveLabel) return { disabled: true, label: inactiveLabel };
  if (status === "needs_review") {
    return { disabled: false, label: "Approve After Manual Review" };
  }
  if (status === "submitted") {
    return { disabled: false, label: "Save Changes for Review" };
  }
  if (status === "ai_approved" || status === "staff_approved") {
    return { disabled: false, label: "Save Changes and Re-review" };
  }
  return {
    disabled: false,
    label: status === "confirmed" ? "Update Confirmed Fields" : "Confirm Reviewed Fields",
  };
}

export function getPassportReviewerLabel(
  passport: ReviewerSource,
  currentUser: { id: string; full_name: string } | null,
) {
  if (passport.verification_reviewer_name?.trim()) {
    return passport.verification_reviewer_name.trim();
  }
  if (!passport.verification_reviewed_by_user_id) return null;
  if (passport.verification_reviewed_by_user_id === currentUser?.id) {
    return currentUser.full_name;
  }
  return "Verified by staff";
}

export function formatPassportVerificationReason(reasonCode: string) {
  const trimmed = reasonCode.trim();
  if (!trimmed) return "Review this field manually.";
  if (trimmed.includes(" ")) return /[.!?]$/.test(trimmed) ? trimmed : `${trimmed}.`;
  const message = trimmed.replaceAll("_", " ").replace(/^./, (letter) => letter.toUpperCase());
  return `${message}.`;
}

function validationIssueMatchesField(
  issue: { field: string; message: string },
  field: PassportReviewFieldName,
) {
  if (issue.field === field) return true;
  const text = `${issue.field} ${issue.message}`.toLowerCase().replaceAll(" ", "_");
  if (field === "surname" || field === "given_names") {
    return text.includes(field) || text.includes("name");
  }
  const aliases: Record<PassportReviewFieldName, string[]> = {
    surname: [],
    given_names: [],
    passport_number: ["passport_number"],
    nationality: ["nationality"],
    place_of_issue: ["place_of_issue"],
    date_of_birth: ["date_of_birth", "birth"],
    date_of_issue: ["date_of_issue", "issue_date"],
    date_of_expiry: ["date_of_expiry", "expiry"],
    sex: ["sex", "gender"],
  };
  return aliases[field].some((alias) => text.includes(alias));
}

