  page: number;
  viewMode: PassportGroupViewMode;
}

export interface PassportDetailNavigationState {
  token: string | null;
  groupId: string;
  includeDeleted: boolean;
  viewState: PassportGroupViewState;
}

const DEFAULT_VIEW_STATE: PassportGroupViewState = {
  search: "",
  submissionFilter: "all",
  sortBy: "name",
  sortOrder: "asc",
  page: 1,
  viewMode: "table",
};

